window.NPC_CHUNK_175 = [{"name":"Rayaldach","cr":16,"xp":76800,"race":"gargoyle","age_category":"Adult","classes":[{"class":"gunslinger","level":12}],"alignment":"NE","size":"Large","type":"monstrous humanoid","sub_types":["earth"],"init":11,"senses":["darkvision 60 ft."],"ac":30,"ac_touch":16,"ac_flat_footed":23,"ac_mods":"+8 armor, +4 Dex, +3 dodge, +6 natural, -1 size","hp":241,"hd":"5d10+12d10+148","hd_value":17,"fort":19,"ref":20,"will":14,"defensive_abilities":["nimble +3"],"dr":"10/magic","speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":40}],"melee":"bite +22 (1d6+6), 2 claws +22 (1d8+6), gore +22 (1d6+6)","ranged":"implanted laser pistol +21 touch (2d6+5 fire), nuclear resonator +21 touch (special +5/15-20)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"grit","details":"1"},{"type":"gun training","details":"laser pistol, nuclear resonator, +5"}],"strength":22,"dexterity":20,"constitution":24,"intelligence":8,"wisdom":13,"charisma":7,"baseatk":17,"cmb":24,"cmd":42,"feats":[{"feat":"Deadly Aim"},{"feat":"Gunsmithing"},{"feat":"Improved Critical (nuclear resonator)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Quick Draw"},{"feat":"Rapid Shot"},{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":22},{"skill":"Perception","value":21},{"skill":"Stealth","value":26}],"languages":["Common","Terran"],"sq":["deeds (bleeding wound [5], dead shot, deadeye, expert loading, gunslinger initiative, gunslinger's dodge, lightning reload, pistol-whip, quick clear, startling shot, targeting, utility shot)","freeze","gunsmith"],"gear":"+4 chain shirt, integrated laser pistol, nuclear resonator, cloak of resistance +3, cybernetic arm, mark I wirejack tendons, prismatic access card (unlocks doors to E8)","during_combat":"Rayaldach prefers to fight with his nuclear resonator when he can, but switches to his implanted laser pistol or to melee as needed (usually just so long as it takes to get into position for another good shot with the resonator. He doesn't pursue foes from this room, but if the PCs enter and/or escape via the restrooms, the gargoyle uses the resonator on that room to collapse it, rendering that route to the bridge inaccessible from that point on.","morale":"Rayaldach fights to the death.","source":"AP 90, Pathfinder RPG Bestiary 137, Pathfinder RPG Ultimate Combat 9"},{"name":"Ophelia","cr":19,"xp":204800,"race":"gargoyle","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of unity","level":17}],"alignment":"LE","size":"Medium","type":"monstrous humanoid","sub_types":["earth"],"templates_applied":"advanced","init":9,"senses":["darkvision 60 ft."],"ac":37,"ac_touch":18,"ac_flat_footed":33,"ac_mods":"+10 armor, +4 deflection, +3 Dex, +1 dodge, +9 natural","hp":323,"hd":"5d10+17d8+220","hd_value":22,"fort":23,"ref":17,"will":25,"save_mods":"+2 vs. mind-affecting effects","resists":["cold 20"],"speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"+3 shocking burst battleaxe +28 (1d8+12/19-20/x3 plus 1d6 electricity), +3 shocking burst claw +27 (1d6+10 plus 1d6 electricity), gore +19 (1d4+3), bite +19 (1d4+3)","ranged":"+4 rail gun +26 touch (3d10+4/x4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"6/day, DC 21, 9d6"}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":17,"spellsprepared_concentration":25,"spellsprepared":[{"spell_level":9,"spell_slots":2,"spells":[{"spell":"meteor swarm","type":"domain"},{"spell":"miracle"}]},{"spell_level":8,"spell_slots":4,"spells":[{"spell":"demand","type":"domain"},{"spell":"fire storm"},{"spell":"greater spell immunity"},{"spell":"quickened freedom of movement"}]},{"spell_level":7,"spell_slots":5,"spells":[{"spell":"destruction"},{"spell":"quickened cure serious wounds","count":2},{"spell":"quickened irradiate"},{"spell":"sunbeam","type":"domain"}]},{"spell_level":6,"spell_slots":6,"spells":[{"spell":"blade barrier","count":2},{"spell":"heal"},{"spell":"planar binding","type":"domain"},{"spell":"quickened hold person"},{"spell":"quickened silence"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"flame strike"},{"spell":"greater command","type":"domain"},{"spell":"quickened cure light wounds"},{"spell":"quickened shield of faith"},{"spell":"spell resistance"},{"spell":"wall of stone"}]},{"spell_level":4,"spell_slots":7,"spells":[{"spell":"cure critical wounds","count":2},{"spell":"death ward"},{"spell":"discern lies","type":"domain"},{"spell":"greater magic weapon"},{"spell":"spell immunity"},{"spell":"unholy blight"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"cure serious wounds","count":2},{"spell":"discharge"},{"spell":"dispel magic"},{"spell":"invisibility purge"},{"spell":"magic vestment","type":"domain"},{"spell":"protection from energy"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"cure moderate wounds","count":3},{"spell":"hold person"},{"spell":"hypnotic pattern","type":"domain"},{"spell":"make whole"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command"},{"spell":"cure light wounds","count":4},{"spell":"divine favor","type":"domain"},{"spell":"sanctuary"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"create water"},{"spell":"guidance"},{"spell":"mending"},{"spell":"stabilize"}]}],"spelldomains":"Nobility, Stars","strength":24,"dexterity":20,"constitution":28,"intelligence":12,"wisdom":26,"charisma":17,"baseatk":17,"cmb":24,"cmd":44,"feats":[{"feat":"Craft Magic Arms and Armor"},{"feat":"Dodge"},{"feat":"Improved Critical (battleaxe)"},{"feat":"Improved Initiative"},{"feat":"Martial Weapon Proficiency (heavy weaponry)"},{"feat":"Power Attack"},{"feat":"Quicken Spell"},{"feat":"Selective Channeling"},{"feat":"Technologist"},{"feat":"Toughness"},{"feat":"Weapon Focus (battleaxe)"}],"skills":[{"skill":"Craft (weapon)","value":15},{"skill":"Disable Device","value":12},{"skill":"Fly","value":17},{"skill":"Intimidate","value":17},{"skill":"Knowledge (engineering)","value":12},{"skill":"Knowledge (religion)","value":15},{"skill":"Linguistics","value":7},{"skill":"Perception","value":22},{"skill":"Stealth","value":17,"special":"+4 in stony environs"}],"languages":["Common","Androffan","Hallit","Lashunta","Terran"],"sq":["freeze","guarded mind","pawn of Unity"],"special_abilities":[{"type":"Pawn of Unity","kind":"Ex","details":"When Ophelia became Unity's pawn, the AI performed invasive and experimental surgical procedures on the gargoyle that increased her Intelligence, Wisdom, and Charisma by 4 each. Unity can communicate with her telepathically and issue orders at will as if via a demand spell-Ophelia cannot save against this effect. A successful DC 20 Sense Motive check is enough to let someone know that Ophelia is being controlled by an external force, but this control can't be disrupted as long as Unity survives."}],"gear":"mwk breastplate, rail gun, Arms of the Iron God, belt of mighty constitution +4, cloak of resistance +3, cybernetic legs, dermal plating mark III, major ring of cold resistance, 5 batteries, 25,000 gp in powdered diamonds","before_combat":"Ophelia casts magic vestment on her armor and greater magic weapon on her rail gun.","during_combat":"Ophelia casts quickened shield of faith on the first round of combat (this bonus is included in her stats above), and then quickened freedom of movement, quickened irradiate, silence, and hold person on the following rounds. When multiple the PCs are in a line, she'll fire on them with her rail gun; otherwise, she uses offensive spells against them. As Unity's favored minion, she doesn't need to attempt caster level checks to successfully cast fire spells within the Divinity Drive's influence. She uses her quickened healing magic on herself during any round where she has fewer than 150 hit points, saving heal for emergencies. She prefers to hold off on casting miracle unless she needs a specific spell she hasn't prepared, but if reduced to fewer than 100 hit points, she attempts to cast miracle to not only restore herself to full hit points but to restore all destroyed evaluator robots to full functionality at her side.","morale":"Ophelia fights to the death.","source":"AP 90, Pathfinder RPG Bestiary 137, 294"},{"name":"Overlord Robot","cr":20,"xp":307200,"race":"Aggregate Unity  robot","age_category":"Adult","alignment":"LE","size":"Large","type":"construct","sub_types":["mythic","robot"],"init":26,"init_special":"M/+6, dual initiative","senses":["all-around vision","blindsight 30 ft.","darkvision 120 ft.","low-light vision","see in darkness","see invisibility"],"auras":["unholy aura (DC 26)"],"ac":44,"ac_touch":22,"ac_flat_footed":35,"ac_mods":"+7 Dex, +4 deflection, +2 dodge, +22 natural, -1 size","hp":397,"hd":"25d10+135 plus 100 point force field","hd_value":25,"fort":14,"ref":23,"will":20,"defensive_abilities":["hardness 20"],"immunities":["cold","construct traits"],"speed":[{"type":"fly","speed":30,"maneuverability":"good"},{"type":"land","speed":50}],"melee":"+3 vorpal battleaxe +38 (2d6+18/19-20/x3), 2 claws +35 (1d8+15)","ranged":"integrated laser rifle +31 touch (3d6+4/19-20 fire)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bleeding strike"},{"type":"combined arms"},{"type":"gravity bomb"},{"type":"mythic power","details":"8/day, surge +1d10"},{"type":"sneak attack","details":"+2d6"}],"strength":33,"dexterity":25,"intelligence":34,"wisdom":22,"charisma":26,"baseatk":25,"cmb":37,"cmd":56,"feats":[{"feat":"Alertness"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Craft Cybernetics"},{"feat":"Craft Robot"},{"feat":"Craft Technological Arms and Armor"},{"feat":"Craft Technological Item"},{"feat":"Critical Focus"},{"feat":"Deadly Aim"},{"feat":"Dodge","type":"mythic"},{"feat":"Exotic Weapon Proficiency (firearms, heavy weaponry)"},{"feat":"Flyby Attack"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (battleaxe)"},{"feat":"Improved Critical (integrated laser cannon)"},{"feat":"Improved Initiative","type":"mythic"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes","type":"mythic"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Staggering Critical"},{"feat":"Technologist"},{"feat":"Toughness","type":"mythic"}],"skills":[{"skill":"Acrobatics","value":32},{"skill":"Bluff","value":31},{"skill":"Craft (mechanical)","value":35},{"skill":"Diplomacy","value":28},{"skill":"Disable Device","value":30},{"skill":"Fly","value":37},{"skill":"Heal","value":28},{"skill":"Intimidate","value":36},{"skill":"Knowledge (arcana, geography, history, planes, religion)","value":35},{"skill":"Knowledge (engineering)","value":40},{"skill":"Linguistics","value":35},{"skill":"Perception","value":38},{"skill":"Perform (oratory)","value":28},{"skill":"Sense Motive","value":38},{"skill":"Spellcraft","value":32},{"skill":"Use Magic Device","value":28}],"languages":["Common","Abyssal","Aklo","Androffan","Aquan","Auran","Celestial","Draconic","Dwarven","Elven","Giant","Gnome","Halfling","Hallit","Ignan","Infernal","Lashunta","Orc","Terran"],"special_abilities":[{"type":"Combined Arms","kind":"Ex","details":"When taking a full-attack action, the overlord robot can attack with its claws, battleaxe, and integrated laser rifle simultaneously."},{"type":"Gravity Bomb","kind":"Ex","details":"As a swift action once every 1d4 rounds, the overlord robot can fire a purple bolt of force from its eye. This bolt has a range of 120 ft. and explodes on impact, dealing 20d6 points of force damage to creatures in a 30-foot radius (Reflex DC 29 half). Creature that fail this save are encapsulated in a sphere of force, as resilient sphere, for 1d6 rounds (Fortitude DC 29 negates). The save DCs are Dexterity-based."}],"gear":"Large +3 vorpal battleaxe, intuition facet","before_combat":"The overlord robot casts unholy aura on itself.","during_combat":"The overlord robot relies on its physical attacks rather than spell-like abilities. It uses its gravity bomb as often as possible, as well as Deadly Aim and Power Attack. If foes are hitting it too often, the overlord swaps out the use of Power Attack for Combat Expertise and begins to use Flyby Attacks to try to limit full attacks against itself.","morale":"The overlord robot fights until destroyed.","source":"AP 90, Pathfinder Campaign Setting: Technology Guide 59","unique_monster":1},{"name":"Alling Third","cr":19,"xp":204800,"race":"Human cyborg-lich","gender":"Male","age_category":"Adult","classes":[{"class":"wizard","level":17}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["human"],"init":9,"auras":["fear (60 ft., DC 20)"],"ac":34,"ac_touch":20,"ac_flat_footed":29,"ac_mods":"+4 armor, +5 deflection, +5 Dex, +10 natural","hp":330,"hd":"17d6+68 plus 200 hp force field","hd_value":17,"fort":12,"ref":15,"will":17,"defensive_abilities":["channel resistance +8 hardness 15","rejuvenation"],"dr":"15/bludgeoning and magic","immunities":["cold","electricity","undead traits"],"speed":[{"type":"land","speed":30}],"melee":"3 claws +11 (1d6+3 plus grab and paralyzing touch)","ranged":"integrated gravity rifle +13 (4d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"combined arms"},{"type":"hand of the apprentice","details":"12/day"},{"type":"paralyzing touch","details":"DC 22"}],"spellsprepared_caster":"wizard","spellsprepared_caster_level":17,"spellsprepared_concentration":26,"spellsprepared":[{"spell_level":9,"spell_slots":2,"spells":[{"spell":"dominate monster"},{"spell":"time stop"}]},{"spell_level":8,"spell_slots":3,"spells":[{"spell":"orb of the void"},{"spell":"quickened dimension door"},{"spell":"stormbolts"}]},{"spell_level":7,"spell_slots":4,"spells":[{"spell":"forcecage"},{"spell":"limited wish"},{"spell":"project image"},{"spell":"quickened lightning bolt"}]},{"spell_level":6,"spell_slots":5,"spells":[{"spell":"chain lightning"},{"spell":"circle of death"},{"spell":"greater discharge"},{"spell":"true seeing"},{"spell":"unwilling shield"}]},{"spell_level":5,"spell_slots":6,"spells":[{"spell":"fabricate"},{"spell":"magic jar"},{"spell":"quickened magic missile","count":2},{"spell":"suffocation"},{"spell":"wall of force"}]},{"spell_level":4,"spell_slots":6,"spells":[{"spell":"dimension door"},{"spell":"greater invisibility"},{"spell":"greater make whole"},{"spell":"phantasmal killer"},{"spell":"shout"},{"spell":"wall of fire"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"discharge"},{"spell":"dispel magic"},{"spell":"displacement"},{"spell":"irradiate"},{"spell":"lightning bolt","count":2}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"ghoul touch"},{"spell":"make whole","count":2},{"spell":"mirror image"},{"spell":"resist energy"},{"spell":"touch of idiocy"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"burning hands"},{"spell":"charm person"},{"spell":"expeditious retreat"},{"spell":"mage armor"},{"spell":"magic missile","count":2},{"spell":"protection from good"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"read magic"}]}],"strength":16,"dexterity":20,"intelligence":29,"wisdom":14,"charisma":15,"baseatk":8,"cmb":11,"cmd":40,"feats":[{"feat":"Ability Focus (paralyzing touch)"},{"feat":"Combat Casting"},{"feat":"Craft Cybernetics"},{"feat":"Craft Technological Item"},{"feat":"Craft Wondrous Item"},{"feat":"Defensive Combat Training"},{"feat":"Heighten Spell"},{"feat":"Improved Initiative"},{"feat":"Quicken Spell"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (evocation)"},{"feat":"Spell Focus (necromancy)"},{"feat":"Technologist"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Craft (mechanical)","value":29},{"skill":"Disable Device","value":22},{"skill":"Heal","value":19},{"skill":"Knowledge (arcana)","value":29},{"skill":"Knowledge (dungeoneering)","value":29},{"skill":"Knowledge (engineering)","value":29},{"skill":"Knowledge (geography)","value":29},{"skill":"Knowledge (local)","value":29},{"skill":"Knowledge (planes)","value":29},{"skill":"Linguistics","value":20},{"skill":"Perception","value":30},{"skill":"Sense Motive","value":14},{"skill":"Spellcraft","value":29},{"skill":"Stealth","value":13}],"languages":["Common","Abyssal","Aklo","Androffan","Auran","Azlanti","Celestial","Draconic","Dwarven","Giant","Hallit","Ignan","Infernal","Jistka","Kelish","Necril","Osiriani","Undercommon"],"sq":["arcane bond (ring of protection +5)","metamagic mastery (5/day)","part machine"],"special_abilities":[{"type":"Combined Arms","kind":"Ex","details":"When taking a full-attack action, Alling Third can simultaneously attack with melee and ranged integrated weapons. He doesn't provoke attacks of opportunity with his integrated gravity rifle when using combined arms."},{"type":"Force Field","kind":"Ex","details":"Alling Third incorporated a force field generator into his mechanical body. Alling is sheathed in a thin layer of shimmering energy that grants him 200 bonus hit points. All damage dealt to the lich while his force field is active is deducted from these hit points first. As long as the force field is active, Alling is immune to critical hits. Alling's force field has fast healing 20, but once these bonus hit points are reduced to 0, the force field shuts down and doesn't reactivate for 24 hours."},{"type":"Integrated Gravity Rifle","kind":"Ex","details":"Alling Third has a built-in gravity rifle. This weapon uses a focused beam of gravitons to create a bolt of force. The integrated gravity rifle has two settings-switching between settings is a swift action. On its pulse setting, it can be used as a typical beam weapon that deals 4d6 points of force damage; on its sustained setting, the weapon creates a stable beam of gravitons rather than a short, destructive burst. In sustained mode, the integrated gravity rifle can be used to move and manipulate objects at a distance, similar to a telekinesis spell in its sustained force or combat maneuver versions. The graviton beam can move objects weighing no more than 350 pounds up to 20 ft. per round. A creature can negate this effect on an object in its possession with a successful DC 27 Reflex save. If used to perform a combat maneuver, the beam uses Alling's CMB with a +4 bonus, and uses his Intelligence modifier in place of his Strength or Dexterity modifier. The save DC is Intelligence-based."},{"type":"Part Machine","kind":"Ex","details":"Alling Third is more than just a Human with cybernetics installed in his body. Most of his current form is machine and his body is undead. In this current form, Alling's Strength is increased by +6, and he can use the touch attack granted to the lich (along with the paralyzing touch special attack) by touching an enemy with his mechanical arms. Alling's current form is also well armored; his mechanical body provides hardness 15 until he is reduced to 50 or fewer hit points. At that point, Alling's channel resistance drops from +8 to +4, but his lich defensive abilities also kick in, and he receives the benefit of his damage reduction. In addition, the cyborg-lich has found ways to incorporate his magic items into his mechanical body."}],"gear":"belt of incredible dexterity +6, cloak of resistance +5, headband of vast intelligence +6, ring of protection +5, spellbook (contains all 0-level spells, all prepared spells, permanency, symbol of death, wish, and 4d12 spells of up to 9th-level of the GM's choice)","before_combat":"Alling Third casts mage armor every day-it lasts for 17 hours. During the times it's not in effect, he keeps other protections in order. He watches the PCs during their journey through his complex to determine the best energy resistance to cast on himself, but doesn't bother if the intruders tend to deal cold or electricity damage.","during_combat":"Alling favors hit-and-run tactics. He uses project image to test and harass the PCs, learning their tactics before confronting them in person. When he finally faces the PCs, he uses dimension door to escape any conflict that is stacked against him, retreating to set up another ambush in his ruins of horror.","morale":"Alling Third is confident in his own abilities, but he always tries to escape a bad situation. He believes that his phylactery is brilliant and indecipherable, so he's confident that if he is destroyed he will always rejuvenate. Alling would never leave his compound; if cornered, he fights until destroyed.","source":"AP 90, Pathfinder RPG Bestiary 188"},{"name":"Aspis Agent Subtier 6-7","cr":4,"xp":1200,"race":"human","age_category":"Adult","classes":[{"class":"ranger","level":2},{"class":"rogue","level":3}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":7,"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 armor, +3 Dex, +1 dodge","hp":40,"hd":"2d10+3d8+12","hd_value":5,"fort":6,"ref":9,"will":4,"defensive_abilities":["evasion","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"rapier +6 (1d6+2/18-20)","ranged":"mwk longbow +9 (1d8/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"evil outsiders +2"},{"type":"sneak attack","details":"+2d6"}],"strength":14,"dexterity":17,"constitution":14,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":4,"cmb":6,"cmd":20,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Weapon Focus (longbow)"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Bluff","value":6},{"skill":"Climb","value":9},{"skill":"Disable Device","value":11},{"skill":"Handle Animal","value":7},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":10},{"skill":"Survival","value":9}],"languages":["Common"],"sq":["rogue talents (combat trick)","track +1","trapfinding +1","wild empathy +1"],"gear":"masterwork chain shirt, masterwork longbow with 20 arrows, rapier, Areshkagal amulet, masterwork thieves' tools, cold iron arrows (10)","before_combat":"The Aspis agents position themselves to best take advantage of their sneak attacks, while maintaining cover if possible, hoping the setting sun and the terrain can both protect them from attack and give them the ability to surprise their foes.","during_combat":"The Aspis agents are under strict orders from Desimire to guard the sphinx's entrance; however, when only one guard remains, she attempts to flee back into the temple and lure pursuing PCs into area B3, where the graven guardians won't attack the Aspis agent but will attack her pursuers.","source":"PFS S3-25"},{"name":"Graven Guardian","cr":5,"xp":1600,"race":"Graven Guardian","age_category":"Adult","alignment":"N","size":"Medium","type":"construct","init":2,"senses":["darkvision 60 ft.","low-light vision"],"ac":20,"ac_touch":12,"ac_flat_footed":18,"ac_mods":"+2 Dex, +8 natural","hp":53,"hd":"6d10+20","hd_value":6,"hp_mods":"fast healing 2","fort":2,"ref":4,"will":3,"dr":"5/adamantine","immunities":["construct traits"],"sr":16,"weaknesses":["faith bound"],"speed":[{"type":"land","speed":40}],"melee":"+1 keen sickle +10 (1d6+5/19-20 plus trip) or slam +9 (1d6+4 plus trip)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"evil weapons"},{"type":"magic weapon"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":0,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"haste","details":"self only"}]}],"strength":16,"dexterity":15,"wisdom":12,"charisma":1,"baseatk":6,"cmb":9,"cmd":21,"sq":["guardian domains (Evil, Trickery)"],"special_abilities":[{"type":"Evil Weapons","kind":"Su","details":"The graven guardian's weapon and slam attacks are treated as evil-aligned. Its magic weapon deals +1d6 points of damage to good targets."},{"type":"Faith Bound","kind":"Su","details":"A graven guardian cannot attack any creature that openly wears or displays the holy or unholy symbol of the deity to which the graven guardian is dedicated unless that creature first attacks the graven guardian."},{"type":"Magic Weapon","kind":"Su","details":"A graven guardian that carries its deity's favored weapon treats that weapon as a +1 weapon as long as it is wielded by the guardian. If the weapon is a melee weapon, it gains the keen weapon special ability."}],"gear":"masterwork sickle","during_combat":"The graven guardian initiates combat by casting haste on itself, then focuses its attacks on the nearest PC not displaying Areshkagal's demonic rune, or the nearest PC to attack it, always attacking a standing target over a prone target if multiple creatures are adjacent to the guardian.","source":"PFS S3-25, Pathfinder RPG Bestiary 3 140"},{"name":"Aglorn Desimire","cr":4,"xp":1200,"race":"human","gender":"Male","age_category":"middle age","classes":[{"class":"conjurer","level":5}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+4 armor, +2 Dex","hp":45,"hd":"5d6+15; 10 temporary","hd_value":5,"fort":2,"ref":3,"will":3,"speed":[{"type":"land","speed":30}],"melee":"dagger +1 (1d4-1/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dimensional steps","details":"150 feet/day"}]},{"frequency":"7/day","spells":[{"spell":"acid dart","details":"1d6+2 acid"}]}],"spellsprepared_caster":"conjurer","spellsprepared_caster_level":5,"spellsprepared_concentration":9,"spellsprepared":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"summon monster III"}]},{"spell_level":2,"spell_slots":4,"spells":[{"spell":"acid arrow"},{"spell":"false life"},{"spell":"scare"},{"spell":"summon monster II"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"alarm"},{"spell":"mage armor"},{"spell":"magic missile","count":2},{"spell":"summon monster I"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"flare"},{"spell":"read magic"},{"spell":"resistance"}]}],"prohibited_schools":"Enchantment, Illusion","strength":9,"dexterity":14,"constitution":12,"intelligence":18,"wisdom":9,"charisma":13,"baseatk":2,"cmb":1,"cmd":13,"feats":[{"feat":"Augment Summoning"},{"feat":"Heighten Spell"},{"feat":"Improved Initiative"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (conjuration)"},{"feat":"Toughness"}],"skills":[{"skill":"Appraise","value":12},{"skill":"Knowledge (arcana)","value":12},{"skill":"Knowledge (planes)","value":12},{"skill":"Knowledge (religion)","value":12},{"skill":"Linguistics","value":12},{"skill":"Perception","value":4},{"skill":"Spellcraft","value":12}],"languages":["Common","Abyssal","Aklo","Aquan","Auran","Celestial","Igan","Infernal","Terran","Undercommon"],"sq":["arcane bond (ring)","summoner's charm (2 rounds)"],"gear":"dagger, spell component pouch, spellbook (contains all 0-level spells, all prepared spells, and the following: 1st- burning hands, comprehend languages, feather fall, grease, hold portal, obscuring mist, shield; 2nd-acid arrow), Aspis cipher key, lesser extend metamagic rod, potion of cure moderate wounds, scroll of see invisibility","before_combat":"If the PCs set of Aglorn's alarm spell on the stairs to C1, he casts mage armor and false life on himself before the Pathfinders reach the cavern.","during_combat":"Aglorn begins combat by summoning monsters to waylay the PCs along the rope bridges and plateaus, doing so as far as his range will allow. He summons creatures in the following order: 1d3 fiendish giant spiders (summon monster III), 1d3 lemures (summon monster III from his bonded item), and 1d3 fiendish dire rats (summon monster II), each using the Augment Summoning feat and 1 charge of Aglorn's lesser extend metamagic rod. Once he can see the PCs, he uses the next round to catch as many of them as possible in a fireball, and casts dispel magic on the first PC he sees flying or otherwise using magic to gain mobility across the treacherous terrain. If he is cornered in melee, he uses his dimensional steps spell like ability to escape and continue the combat at range.","morale":"Aglorn knows the entire Aspis Consortium effort in the Hao Jin Tapestry hinges on him maintaining control of the Diamond Gate, and he fights to the death to defend it.","source":"PFS S3-25"},{"name":"Aspis Archer","cr":3,"xp":800,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":4}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+4 armor, +3 Dex","hp":38,"hd":"4d10+12","hd_value":4,"fort":6,"ref":4,"will":2,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":30}],"melee":"club +6 (1d6+2)","ranged":"mwk composite longbow +9 (1d8+4/x3)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":17,"constitution":14,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":4,"cmb":6,"cmd":19,"feats":[{"feat":"Deadly Aim"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Weapon Focus (longbow)"},{"feat":"Weapon Specialization (longbow)"}],"skills":[{"skill":"Climb","value":9},{"skill":"Handle Animal","value":6},{"skill":"Knowledge (dungeoneering)","value":5},{"skill":"Knowledge (engineering)","value":5}],"languages":["Common"],"sq":["armor training 1"],"gear":"masterwork chain shirt, club, masterwork composite longbow (+2 Str) with 20 arrows, +1 seeking arrows (6), potion of cure light wounds","during_combat":"The archer focuses his attacks on PCs that can't be reached by Aglorn's summoned creatures, such as flying or climbing PCs, leaving those within range of the summoned horde to the monsters' devices. He saves his seeking arrows for use against targets that have concealment (such as those that move into areas of darkness or dim light).","morale":"As long as Aglorn lives, the archer fights to the death. If his commander has been defeated, however, the archer surrenders if reduced to 10 or fewer hit points.","source":"PFS S3-25"},{"name":"Aglorn Desimire Subtier 6-7","cr":8,"xp":4800,"race":"human","gender":"Male","age_category":"middle age","classes":[{"class":"conjurer","level":9}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":6,"ac":22,"ac_touch":14,"ac_flat_footed":19,"ac_mods":"+4 armor, +1 deflection, +2 Dex, +1 dodge, +4 shield","hp":75,"hd":"9d6+27; 14 temporary","hd_value":9,"fort":6,"ref":7,"will":8,"speed":[{"type":"fly","speed":40},{"type":"land","speed":30}],"melee":"mwk cold iron dagger +4 (1d4-1/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dimensional steps","details":"270 feet/day"}]},{"frequency":"7/day","spells":[{"spell":"acid dart","details":"1d6+4 acid"}]}],"spellsprepared_caster":"conjurer","spellsprepared_caster_level":9,"spellsprepared_concentration":13,"spellsprepared":[{"spell_level":5,"spell_slots":2,"spells":[{"spell":"overland flight"},{"spell":"summon monster V"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"black tentacles"},{"spell":"fear"},{"spell":"summon monster IV"},{"spell":"wall of fire"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"fireball","count":2},{"spell":"stinking cloud"},{"spell":"wind wall"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"acid arrow","count":2},{"spell":"darkvision"},{"spell":"false life"},{"spell":"scorching ray"},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"alarm"},{"spell":"burning hands"},{"spell":"mage armor"},{"spell":"magic missile","count":2},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"flare"},{"spell":"read magic"},{"spell":"resistance"}]}],"prohibited_schools":"Enchantment, Illusion","strength":9,"dexterity":14,"constitution":12,"intelligence":18,"wisdom":10,"charisma":13,"baseatk":4,"cmb":3,"cmd":17,"feats":[{"feat":"Alertness (when within reach of Duchess)"},{"feat":"Augment Summoning"},{"feat":"Dodge"},{"feat":"Heighten Spell"},{"feat":"Improved Familiar"},{"feat":"Improved Initiative"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (conjuration)"},{"feat":"Toughness"}],"skills":[{"skill":"Appraise","value":16},{"skill":"Knowledge (arcana)","value":16},{"skill":"Knowledge (planes)","value":16},{"skill":"Knowledge (religion)","value":16},{"skill":"Linguistics","value":16},{"skill":"Perception","value":9,"special":"+2 when within reach of Duchess"},{"skill":"Spellcraft","value":16}],"languages":["Common","Abyssal","Aklo","Aquan","Auran","Azlanti","Celestial","Elven","Igan","Infernal","Osiriani","Sylvan","Terran","Undercommon"],"sq":["arcane bond (imp named Duchess)","summoner's charm (4 rounds)"],"gear":"masterwork cold iron dagger, cloak of resistance +2, ring of protection +1, spell component pouch, spellbook (contains all 0-level spells, all prepared spells, and the following: 1st-comprehend languages, feather fall, grease, hold portal, obscuring mist, summon monster I; 2nd-scare, summon monster II; 3rd-haste, summon monster III; 4th- dimensional anchor), Aspis cipher book, extend metamagic rod, potion of cure serious wounds, scroll of blink, scroll of lesser globe of invulnerability","before_combat":"Aglorn begins each day by casting false life, mage armor, and overland flight. If the PCs set off his alarm spell on the stairs to C1, he casts extended wind wall and shield before the Pathfinders reach the cavern.","during_combat":"Aglorn begins combat by summoning monsters to waylay the PC along the rope bridges and plateaus, doing so as far as his range will allow. He summons creatures in the following order: 1d3 fiendish giant wasps (summon monster V) and 1d3 fiendish wolverines (summon monster IV), each using  the Augment Summoning feat and 1 charge of Aglorn's extend metamagic rod. Once he can see the PCs, he uses the next round to catch as many of them as possible in a fireball, and casts dispel magic on the first PC he sees flying or otherwise using magic to gain mobility across the treacherous terrain. If the opportunity presents itself, Aglorn splits the party with a wall of fire and then uses fear to drive fleeing opponents toward the flames. If he is cornered in melee, he uses his dimensional steps spell-like ability to escape and continue the combat at range.","morale":"Aglorn knows the entire Aspis Consortium effort in the Hao Jin Tapestry hinges on him maintaining control of the Diamond Gate, and he fights to the death to defend it.","source":"PFS S3-25"},{"name":"Duchess","xp":0,"race":"imp familiar","gender":"Female","age_category":"Adult","alignment":"LE","size":"Tiny","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":3,"senses":["darkvision 60 ft.","detect good","detect magic","see in darkness"],"ac":22,"ac_touch":16,"ac_flat_footed":18,"ac_mods":"+3 Dex, +1 dodge, +6 natural, +2 size","hp":30,"hd":"3d10","hd_value":3,"hp_mods":"fast healing 2","fort":3,"ref":6,"will":7,"defensive_abilities":["improved evasion"],"dr":"5/good or silver","immunities":["fire","poison"],"resists":["acid 10","cold 10"],"speed":[{"type":"fly","speed":50,"maneuverability":"perfect"},{"type":"land","speed":20}],"melee":"sting +9 (1d4 plus poison)","space":"2-1/2 ft.","reach":"0 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"invisibility","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"augury"},{"spell":"suggestion"}]},{"frequency":"1/week","spells":[{"spell":"commune","details":"CL 12th, 6 questions"}]}],"strength":10,"dexterity":17,"constitution":10,"intelligence":13,"wisdom":12,"charisma":14,"baseatk":4,"cmb":5,"cmd":16,"feats":[{"feat":"Dodge"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Bluff","value":8},{"skill":"Fly","value":21},{"skill":"Knowledge (arcana)","value":13},{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":13},{"skill":"Spellcraft","value":13}],"languages":["Common","Infernal"],"sq":["change shape (boar, giant spider, rat, or raven; beast shape I)"],"special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 13; frequency 1/round for 6 rounds; effect 1d2 Dex; cure 1 save."}],"during_combat":"If Teenoch has allied with the PCs and is present here, Duchess becomes distracted and flies off to fight the demon instead of assisting Aglorn in combat. If focused on the PCs, Duchess becomes invisible and flies among the PCs, stinging them when she can flank with summoned creatures.","morale":"Duchess is inexorably bound to Aglorn and the devil cannot abandon her master while he lives. If Aglorn dies, however, Duchess becomes invisible and attempts to flee.","source":"PFS S3-25, Pathfinder RPG Bestiary 78"},{"name":"Aspis Consortium Guard","cr":3,"xp":800,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":2},{"class":"rogue","level":2}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"ac":20,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+6 armor, +2 Dex, +1 dodge, +1 shield","hp":34,"hd":"2d10+2d8+10","hd_value":4,"fort":5,"ref":6,"will":2,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1","evasion"],"speed":[{"type":"land","speed":20}],"melee":"mwk rapier +7 (1d6+1/18-20)","ranged":"longbow +6 (1d8+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+1d6"}],"strength":12,"dexterity":16,"constitution":14,"intelligence":13,"wisdom":10,"charisma":10,"baseatk":3,"cmb":4,"cmd":18,"feats":[{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Improved Feint"},{"feat":"Iron Will"},{"feat":"Skill Focus (Bluff)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":4},{"skill":"Bluff","value":10},{"skill":"Climb","value":0},{"skill":"Perception","value":7},{"skill":"Sense Motive","value":7},{"skill":"Stealth","value":4},{"skill":"Survival","value":6},{"skill":"Swim","value":1}],"languages":["Common","Infernal"],"sq":["rogue talents (finesse rogue)","trapfinding +1"],"gear":"chainmail, light steel shield, masterwork rapier, longbow with 20 arrows, potion of cure moderate wounds, potion of invisibility","before_combat":"If forewarned of the PCs' approach, the guards drink their potions of invisibility to begin combat with sneak attacks.","during_combat":"The guards attempt to flank enemies if possible; if this proves impractical, they feint to gain sneak attacks against their enemies.","morale":"The guards fight to the death as long as Orlicino and Lyone are alive and fighting; if both of their leaders fall, flee, or surrender, the remaining guards attempt to flee downstairs to seek the protection of the cult. In this event, they fall victim to the trap in area D and perish.","source":"PFS S3-26"},{"name":"Orlicino","cr":5,"xp":1600,"race":"Tiefling","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":6}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["native"],"init":4,"init_special":"+2 underground","senses":["darkvision 60 ft."],"ac":20,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+7 armor, +3 Dex","hp":55,"hd":"6d10+18","hd_value":6,"fort":7,"ref":9,"will":3,"resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"land","speed":20}],"melee":"mwk greatsword +8 (2d6+1/19-20)","ranged":"+1 longbow +12 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"humans +4, lawful outsiders +2"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"darkness"}]}],"spellsprepared_caster":"ranger","spellsprepared_caster_level":3,"spellsprepared_concentration":4,"spellsprepared":[{"spell_level":1,"spell_slots":2,"spells":[{"spell":"alarm"},{"spell":"gravity bow"}]}],"strength":13,"dexterity":18,"constitution":14,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":6,"cmb":7,"cmd":21,"feats":[{"feat":"Deadly Aim"},{"feat":"Endurance"},{"feat":"Point Blank Master"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Weapon Focus (longbow)"}],"skills":[{"skill":"Bluff","value":1},{"skill":"Climb","value":7},{"skill":"Intimidate","value":8},{"skill":"Perception","value":10,"special":"+2 underground"},{"skill":"Stealth","value":12,"special":"+2 underground"},{"skill":"Survival","value":10},{"skill":"Swim","value":7}],"languages":["Common","Infernal"],"sq":["favored terrain (underground +2)","hunter's bond (companions)","track +3","wild empathy +5"],"gear":"+1 breastplate, +1 longbow with 40 arrows, masterwork greatsword, 25 gp, potion of cure serious wounds","before_combat":"Orlicino casts gravity bow as soon as he becomes aware of the PCs' approach, increasing the damage dealt by his bow by one size category (2d6) for 3 minutes. He then climbs to the top of the fountain and readies an arrow to fire at the first person down the staircase.","during_combat":"Orlicino uses a move action on the first round and every second round following to activate his hunter's bond for his teammates' benefit, targeting any Human among the PCs. Every other round (or if lacking a suitable Human target) he makes full attacks using Deadly Aim. He uses his bow as long as possible, even if enemies climb onto the fountain to engage him in melee, as his Point Blank Mastery feat allows him to make ranged attacks with his longbow without provoking attacks of opportunity.","morale":"Orlicino doesn't run until Lyone has surrendered, fled, or been killed, in which case Orlicino runs for the balcony and attempts to climb up the interior of the well.","source":"PFS S3-26, Pathfinder RPG Bestiary 264"},{"name":"Lyone Ekonian","cr":7,"xp":3200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"eldritch knight","level":2},{"class":"fighter","level":1},{"class":"transmuter","level":5}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":17,"ac_touch":13,"ac_flat_footed":15,"ac_mods":"+4 armor, +1 deflection, +2 Dex","hp":77,"hd":"3d10+5d6+29; 11 temporary","hd_value":8,"fort":9,"ref":6,"will":7,"speed":[{"type":"land","speed":30}],"melee":"+1 falcata +11 (1d8+6/19-20/x3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"5/day","spells":[{"spell":"telekinetic fist","details":"1d4+2 bludgeoning"}]}],"spellsprepared_caster":"transmuter","spellsprepared_caster_level":6,"spellsprepared_concentration":8,"spellsprepared":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"blink"},{"spell":"keen edge"},{"spell":"vampiric touch"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"cat's grace"},{"spell":"false life"},{"spell":"mirror image","count":2},{"spell":"see invisibility"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"alarm"},{"spell":"mage armor"},{"spell":"shield"},{"spell":"true strike"},{"spell":"vanish"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"touch of fatigue"}]}],"prohibited_schools":"Enchantment, Evocation","strength":18,"dexterity":14,"constitution":16,"intelligence":14,"wisdom":10,"charisma":8,"baseatk":5,"cmb":9,"cmd":22,"feats":[{"feat":"Arcane Strike"},{"feat":"Cleave"},{"feat":"Combat Casting"},{"feat":"Exotic Weapon Proficiency (falcata)"},{"feat":"Power Attack"},{"feat":"Scribe Scroll"},{"feat":"Silent Spell"},{"feat":"Weapon Focus (falcata)"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Knowledge (arcana)","value":10},{"skill":"Knowledge (dungeoneering)","value":8},{"skill":"Knowledge (history)","value":10},{"skill":"Knowledge (nobility)","value":8},{"skill":"Perception","value":8},{"skill":"Spellcraft","value":13}],"languages":["Common","Elven","Varisian"],"sq":["arcane bond (falcata)","physical enhancement +2 (Con)"],"gear":"+1 falcata, ring of protection +1, cloak of resistance +2, belt of giant strength +2, wayfinder, spell component pouch, spellbook (contains all prepared spells, all cantrips, and the following spells: 1st-animate rope, disguise self, feather fall, grease; 2nd-mirror image, web; 3rd-dispel magic), 50 gp, potion of cure serious wounds","before_combat":"Lyone casts mage armor and false life daily, both of which are already reflected in his statistics. Before engaging in combat, he casts keen edge, cat's grace, mirror image, and shield.","during_combat":"Lyone hangs back and attempts to finish casting his preparatory spells while his underlings fight. Once he feels sufficiently prepared or is engaged in melee, he fights with his falcata, always using Power Attack and Arcane Strike. If adjacent to multiple opponents he uses Cleave rather than iterative attacks. After losing 20 hit points, he casts vampiric touch to heal himself. When reduced to one-third of his total hit points, he casts blink and continues fighting.","morale":"If reduced to 10 hit points or less, he casts vanish to turn invisible for 6 rounds and attempts to flee, but is extremely willing to surrender given the opportunity.","base_statistics":"When not under the effects of mage armor and false life, Lyone's statistics are: AC 13, flat-footed 11; hp 66.","source":"PFS S3-26"},{"name":"Aspis Consortium Guard Subtier 10-11","cr":6,"xp":2400,"race":"human","age_category":"Adult","classes":[{"class":"fighter","level":4},{"class":"rogue","level":3}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"ac":21,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+7 armor, +3 Dex, +1 shield","hp":64,"hd":"4d10+3d8+25","hd_value":7,"fort":7,"ref":7,"will":4,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1","evasion","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"+1 rapier +11 (1d6+4/18-20)","ranged":"longbow +9 (1d8/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":12,"dexterity":16,"constitution":14,"intelligence":13,"wisdom":10,"charisma":10,"baseatk":6,"cmb":7,"cmd":20,"feats":[{"feat":"Combat Expertise"},{"feat":"Greater Feint"},{"feat":"Improved Feint"},{"feat":"Iron Will"},{"feat":"Skill Focus (Bluff)"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (rapier)"},{"feat":"Weapon Specialization (rapier)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Bluff","value":13},{"skill":"Climb","value":4},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":8},{"skill":"Survival","value":7},{"skill":"Swim","value":4}],"languages":["Common","Infernal"],"sq":["armor training 1","rogue talents (finesse rogue)","trapfinding +1"],"gear":"+1 chainmail, light steel shield, +1 rapier, longbow with 20 arrows, potion of cure moderate wounds, potion of invisibility","before_combat":"If forewarned of the PCs' approach, the guards drink their potions of invisibility to begin combat with a sneak attack.","during_combat":"The guards attempt to flank enemies if possible; if this proves impractical, they feint to gain sneak attacks against their enemies.","morale":"The guards fight to the death if either Lyone or Orlicino are active in the battle; if both leaders fall, flee, or surrender, any remaining guards flee downstairs seeking the cultists' aid. In this event, the guards perish when they activate the trap on level D, plummeting to their deaths in the well's central shaft.","source":"PFS S3-26"},{"name":"Orlicino Subtier 10-11","cr":8,"xp":4800,"race":"Tiefling","gender":"Male","age_category":"Adult","classes":[{"class":"ranger","level":9}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["native"],"init":4,"init_special":"+4 underground","senses":["darkvision 60 ft."],"ac":23,"ac_touch":13,"ac_flat_footed":20,"ac_mods":"+7 armor, +3 Dex, +3 natural","hp":81,"hd":"9d10+27","hd_value":9,"fort":8,"ref":10,"will":6,"defensive_abilities":["evasion"],"resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"land","speed":20}],"melee":"mwk greatsword +12 (2d6+3/19-20)","ranged":"+1 composite longbow +16 (1d8+3/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"humans +4, lawful outsiders +2"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"darkness"}]}],"spellsprepared_caster":"ranger","spellsprepared_caster_level":6,"spellsprepared_concentration":7,"spellsprepared":[{"spell_level":2,"spell_slots":1,"spells":[{"spell":"barkskin"}]},{"spell_level":1,"spell_slots":3,"spells":[{"spell":"gravity bow"},{"spell":"jump"},{"spell":"longstrider"}]}],"strength":14,"dexterity":18,"constitution":14,"intelligence":10,"wisdom":12,"charisma":8,"baseatk":9,"cmb":11,"cmd":25,"feats":[{"feat":"Deadly Aim"},{"feat":"Endurance"},{"feat":"Iron Will"},{"feat":"Point Blank Master"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Weapon Focus (composite longbow)"}],"skills":[{"skill":"Bluff","value":1},{"skill":"Climb","value":11},{"skill":"Intimidate","value":11},{"skill":"Perception","value":13,"special":"+4 underground"},{"skill":"Stealth","value":15,"special":"+4 underground"},{"skill":"Survival","value":13},{"skill":"Swim","value":11}],"languages":["Common","Infernal"],"sq":["evasion","favored terrain (mountain +2, underground +4)","hunter's bond (companions)","swift tracker","track +4","wild empathy +8","woodland stride"],"gear":"+1 breastplate, +1 composite longbow (+2 Str) with 40 arrows, masterwork greatsword, lesser bracers of archery, 25 gp, potion of cure serious wounds","before_combat":"Orlicino casts longstrider, barkskin, and gravity bow (which increases his bow's base damage to 2d6 for 6 minutes) as soon as he becomes aware of the PCs' approach. He then climbs to the top of the fountain and readies an arrow to fire at the first person down the staircase.","during_combat":"Orlicino uses a move action on the first round and every second round thereafter to activate his hunter's bond for his teammates' benefit, targeting any Human among the PCs. Every other round (or if lacking a suitable Human target) he makes full attacks using Rapid Shot and Deadly Aim. He uses his bow as long as possible, even if enemies climb on the fountain to engage him in melee, since his Point Blank Master feat allows him to make ranged attacks with his bow without provoking attacks of opportunity.","morale":"Orlicino doesn't run until Lyone has surrendered, fled, or been killed, in which case he runs for the balcony and attempts to climb the well's shaft to escape.","source":"PFS S3-26, Pathfinder RPG Bestiary 264"},{"name":"Lyone Ekonian Subtier 10-11","cr":10,"xp":9600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"eldritch knight","level":5},{"class":"fighter","level":1},{"class":"transmuter","level":5}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":18,"ac_touch":14,"ac_flat_footed":16,"ac_mods":"+4 armor, +1 deflection, +2 Dex, +1 insight","hp":104,"hd":"6d10+5d6+38; 14 temporary","hd_value":11,"fort":11,"ref":7,"will":8,"speed":[{"type":"land","speed":30}],"melee":"+1 falcata +14 (1d8+6/19-20/x3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"5/day","spells":[{"spell":"telekinetic fist","details":"1d4+2 bludgeoning"}]}],"spellsprepared_caster":"transmuter","spellsprepared_caster_level":9,"spellsprepared_concentration":11,"spellsprepared":[{"spell_level":5,"spell_slots":2,"spells":[{"spell":"baleful polymorph"},{"spell":"mage's faithful hound"}]},{"spell_level":4,"spell_slots":3,"spells":[{"spell":"dimension door"},{"spell":"enervation"},{"spell":"mass reduce person"}]},{"spell_level":3,"spell_slots":4,"spells":[{"spell":"blink"},{"spell":"keen edge"},{"spell":"vampiric touch","count":2}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"cat's grace"},{"spell":"false life"},{"spell":"mirror image","count":2},{"spell":"see invisibility"},{"spell":"web"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"animate rope"},{"spell":"mage armor"},{"spell":"shield"},{"spell":"true strike"},{"spell":"vanish","count":2}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"message"},{"spell":"prestidigitation"},{"spell":"touch of fatigue"}]}],"prohibited_schools":"Enchantment, Evocation","strength":18,"dexterity":14,"constitution":16,"intelligence":14,"wisdom":10,"charisma":8,"baseatk":8,"cmb":14,"cmd":28,"feats":[{"feat":"Arcane Strike"},{"feat":"Cleave"},{"feat":"Combat Casting"},{"feat":"Exotic Weapon Proficiency (falcata)"},{"feat":"Great Cleave"},{"feat":"Power Attack"},{"feat":"Scribe Scroll"},{"feat":"Silent Spell"},{"feat":"Weapon Focus (falcata)"},{"feat":"Weapon Specialization (falcata)"}],"skills":[{"skill":"Acrobatics","value":13},{"skill":"Knowledge (arcana)","value":11},{"skill":"Knowledge (dungeoneering)","value":10},{"skill":"Knowledge (history)","value":11},{"skill":"Knowledge (nobility)","value":10},{"skill":"Perception","value":11},{"skill":"Spellcraft","value":16}],"languages":["Common","Elven","Varisian"],"sq":["arcane bond (falcata)","physical enhancement +2 (Con)"],"special_abilities":[{"type":"Resonant Ioun Stone Abilities","details":"Lyone receives a +2 insight bonus to CMB and CMD from his dusty rose quartz ioun stone in addition to the normal +1 insight bonus to AC because the ioun stone is embedded in a special notch in his stolen wayfinder. For more information on ioun stone resonant powers and their interaction with wayfinders, see Pathfinder Campaign Setting: Seekers of Secrets."}],"gear":"+1 falcata, ring of protection +1, cloak of resistance +2, belt of giant strength +2, wayfinder w/ dusty rose prism ioun stone, spell component pouch, spellbook (warded with explosive runes [6d6 damage, DC 15 Reflex save for half, reader gets no save] and contains all prepared spells, all cantrips, and the following spells: 1st-alarm, disguise self, feather fall, grease; 2nd-spider climb; 3rd-dispel magic, explosive runes, haste; 4th-elemental body I, fear), 62 gp, potion of cure serious wounds","before_combat":"Lyone casts mage armor and false life daily, and both are reflected in his statistics. Before engaging in combat, he casts keen edge, cat's grace, mirror image, and shield.","during_combat":"Lyone initially hangs back and attempts to hamper opponents with mass reduce person and animate rope while his underlings fight. After using up his ranged spells he wades into melee with his falcata, always using Power Attack and Arcane Strike. Facing adjacent opponents, he uses Cleave rather than iterative attacks. Whenever he loses 20 or more hit points, he casts vampiric touch to heal himself (he can do so up to three times; twice from his prepared spells and once by channeling the spell through his arcane bond). When reduced to half his hit points, he casts blink and continues fighting.","morale":"If reduced to 20 hit points or less, Lyone casts dimension door to teleport to the surface and flees, leaving his group behind. If that fails, he casts vanish to turn invisible for 9 rounds, and attempts to flee, but is extremely willing to surrender given the opportunity.","source":"PFS S3-26"},{"name":"Lissalan Cultist","cr":4,"xp":1200,"race":"human","age_category":"Adult","classes":[{"class":"cleric of Lissala","level":3},{"class":"fighter","level":2}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":4,"ac":18,"ac_touch":10,"ac_flat_footed":18,"ac_mods":"+6 armor, +2 shield","hp":51,"hd":"3d8+2d10+23","hd_value":5,"fort":9,"ref":1,"will":4,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":20}],"melee":"mwk flail +8 (1d8+2)","ranged":"mwk light crossbow +5 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"4/day, DC 14, 2d6"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"4/day","spells":[{"spell":"blast rune","details":"3 rounds, 1d6+1 energy damage"},{"spell":"touch of evil","details":"1 rounds"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":3,"spellsprepared_concentration":4,"spellsprepared":[{"spell_level":2,"spell_slots":2,"spells":[{"spell":"aid"},{"spell":"align weapon"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"entropic shield"},{"spell":"protection from good"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"read magic"},{"spell":"resistance"}]}],"spelldomains":"Evil, Rune","strength":14,"dexterity":10,"constitution":16,"intelligence":10,"wisdom":13,"charisma":12,"baseatk":4,"cmb":6,"cmd":16,"feats":[{"feat":"Channel Smite"},{"feat":"Combat Casting"},{"feat":"Improved Channel"},{"feat":"Improved Initiative"},{"feat":"Scribe Scroll"},{"feat":"Toughness"},{"feat":"Weapon Focus (flail)"}],"skills":[{"skill":"Knowledge (arcana)","value":5},{"skill":"Knowledge (history)","value":5},{"skill":"Knowledge (religion)","value":7},{"skill":"Linguistics","value":4},{"skill":"Perception","value":8},{"skill":"Spellcraft","value":5}],"languages":["Common","Thassilonian"],"sq":["aura"],"gear":"masterwork breastplate, masterwork heavy steel shield, masterwork flail, masterwork light crossbow, spell component pouch, wooden holy symbol, potion of cure moderate wounds, scroll of dispel magic, unholy water (2)","before_combat":"If alerted to approaching enemies, the cultists wait until they can hear the PCs on the stairs and cast aid, entropic shield, and protection from good, in that order.","during_combat":"To begin, two cultists take positions facing the stairs and engage the PCs in combat with their crossbows. The other two position themselves along the wall on either side of the staircase exit and lay down blast runes in the four squares directly in front of the stairs, renewing them as needed if the party doesn't take the bait and rush into action. Once the PCs are in the room, all four cultists cast divine favor and engage the party in melee. The cultists use the Channel Smite feat with each attack they make until they are out of channeling attempts.","morale":"After losing half their hit points, the cultists cast cure light wounds on themselves. If reduced to 10 or fewer hit points, they drink their potions. Otherwise, the cultists fight to the death in defense of their goddess's holy site.","source":"PFS S3-26"},{"name":"Heshlak","cr":6,"xp":2400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":2},{"class":"inquisitor of Lissala","level":5}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":5,"ac":21,"ac_touch":14,"ac_flat_footed":17,"ac_mods":"+5 armor, +4 Dex, +2 shield","hp":63,"hd":"2d10+5d8+26","hd_value":7,"fort":9,"ref":5,"will":5,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":30}],"melee":"+1 agile whip +11 (1d3+5) or mwk scimitar +7 (1d6+1/18-20)","ranged":"heavy crossbow +9 (1d10/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bane","details":"5 rounds/day"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect alignment"}]},{"frequency":"4/day","spells":[{"spell":"blast rune","details":"5 rounds, 1d6+2 energy damage"}]},{"frequency":"5 rounds/day","spells":[{"spell":"discern lies"}]}],"spellsknown_caster":"inquisitor","spellsknown_caster_level":5,"spellsknown_concentration":5,"spellsknown":[{"spell_level":2,"spell_slots":2,"spells":[{"spell":"detect thoughts"},{"spell":"flames of the faithful"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"bane"},{"spell":"bless"},{"spell":"command"},{"spell":"cure light wounds"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"daze"},{"spell":"light"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"stabilize"}]}],"spelldomains":"Rune","strength":12,"dexterity":18,"constitution":14,"intelligence":8,"wisdom":13,"charisma":10,"baseatk":5,"cmb":9,"cmd":20,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Reflexes"},{"feat":"Improved Whip Mastery"},{"feat":"Tandem Trip"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (whip)"},{"feat":"Whip Mastery"}],"skills":[{"skill":"Intimidate","value":12},{"skill":"Knowledge (religion)","value":5},{"skill":"Linguistics","value":2},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":13},{"skill":"Survival","value":11}],"languages":["Common","Shoanti","Skald","Thassilonian","Varisian"],"sq":["cunning initiative","detect alignment","judgment 2/day","monster lore +1","solo tactics","stern gaze","track +2"],"special_abilities":[{"type":"Bane","kind":"Su","details":"Heshlak can imbue one of her weapons with the bane weapon special ability as a swift action. She must select one creature type when she uses this ability (and a subtype if the creature type is humanoid or outsider). Once selected, the type can be changed as a swift action. This ability lasts for a number of rounds per day equal to her inquisitor level. These rounds don't need to be consecutive."},{"type":"Improved Whip Mastery","kind":"Ex","details":"When wielding a whip, Heshlak threatens an area equal to her natural reach plus 5 feet."},{"type":"Judgments","kind":"Su","details":"Heshlak can pronounce judgment on her foes as a swift action. Starting when the judgment is made, she receives a bonus or special ability based on the type of judgment made. Once activated, this ability lasts until the combat ends, at which point all of the bonuses immediately end. She must participate in the combat to gain these bonuses. If she is frightened, panicked, paralyzed, stunned, unsconscious, or otherwise prevented from participating in combat, the ability doesn't end, but the bonuses don't resume until she can participate in the combat again. When Heshlak uses this ability, she must select one type of judgment to make. As a swift action, she can change this judgment to another type. The two judgment types Heshlak uses in this combat are as follows: Destruction: Heshlak is filled with divine wrath, gaining a +2 profane bonus on all weapon damage rolls. Protection: Heshlak is surrounded by a protective aura, granting a +2 profane bonus to Armor Class."},{"type":"Solo Tactics","kind":"Ex","details":"All of Heshlak's allies are treated as if they possessed the same teamwork feats as her for the purpose of determining whether Heshlak receives a bonus from her teamwork feats. Her allies don't receive any bonuses from these feats unless they actually posses the feats themselves. The allies' positioning and actions must still meet the prerequisities listed in the teamwork feat for Heshlak to receive the listed bonus."},{"type":"Tandem Trip","kind":"Ex","details":"Whenever Heshlak makes a trip attempt against an enemy who is threatened by an ally with this feat, she may roll twice and take the better result."},{"type":"Whip Mastery","kind":"Ex","details":"Heshlak doesn't provoke attacks of opportunity when making attacks with a whip. Additionally, she can deal lethal damage with a whip, but can still deal nonlethal damage when she chooses. Finally, she can deal damage with a whip despite a creature's armor bonus or natural armor bonus."}],"gear":"+1 mithral shirt, heavy steel shield, +1 agile whip, masterwork scimitar, heavy crossbow with 10 bolts, spell component pouch, wooden holy symbol, potion of cat's grace, potion of cure serious wounds","before_combat":"If warned of the PCs' approach, Heshlak casts bless on herself and the cultists, drinks her potion of cat's grace, and casts flames of the faithful on her whip, granting it the flaming burst weapon special property for 6 rounds (caster level +1 round as a transmutation spell).","during_combat":"Once the PCs are in range, Heshlak casts spiritual weapon on a spellcaster, pronounces a judgment of destruction against the party, and moves forward to threaten any PC entering the room with her whip. She tries to stay out of the PCs' reach, letting cultists engage them while using her whip's reach to dominate the floor, expending a swift action to activate her bane ability, selecting the most common humanoid subtype among the Pathfinders. She positions herself to have multiple PCs within 10 feet, if possible, and uses her action each round to either strike a target of the subtype of her bane ability or to make trip attacks. She gleefully takes attacks of opportunity against anyone within range who provokes them. If attacked, she trips her assailant and steps away, laying into them with the whip if trapped. Confronted by multiple assailants at once, she switches her judgment to protection and lashes about her as best she can.","morale":"Heshlak refuses to surrender. If brought below 15 hit points, and a PC is between her and the opening to the  central well, she attempts a bull rush to knock her enemy and herself into the shaft for a 60-foot drop.","source":"PFS S3-26, Advanced Player's Guide 38"},{"name":"Lissalan Cultist Subtier 10-11","cr":7,"xp":3200,"race":"human","age_category":"Adult","classes":[{"class":"cleric of Lissala","level":6},{"class":"fighter","level":2}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":4,"ac":19,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+7 armor, +2 shield","hp":79,"hd":"6d8+2d10+38","hd_value":8,"fort":11,"ref":2,"will":7,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":20}],"melee":"+1 flail +10 (1d8+3)","ranged":"mwk light crossbow +7 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"6/day, DC 16, 3d6"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"5/day","spells":[{"spell":"blast rune","details":"6 rounds, 1d6+3 energy damage"},{"spell":"touch of evil","details":"3 rounds"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":6,"spellsprepared_concentration":8,"spellsprepared":[{"spell_level":3,"spell_slots":3,"spells":[{"spell":"cure serious wounds"},{"spell":"invisibility purge"},{"spell":"magic circle against good"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"aid"},{"spell":"align weapon"},{"spell":"cure moderate wounds"},{"spell":"hold person"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"doom"},{"spell":"entropic shield"},{"spell":"erase"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"read magic"},{"spell":"resistance"}]}],"spelldomains":"Evil, Rune","strength":14,"dexterity":10,"constitution":16,"intelligence":10,"wisdom":14,"charisma":12,"baseatk":6,"cmb":8,"cmd":18,"feats":[{"feat":"Channel Smite"},{"feat":"Combat Casting"},{"feat":"Extra Channel"},{"feat":"Improved Channel"},{"feat":"Improved Initiative"},{"feat":"Scribe Scroll"},{"feat":"Toughness"},{"feat":"Weapon Focus (flail)"}],"skills":[{"skill":"Knowledge (arcana)","value":6},{"skill":"Knowledge (history)","value":6},{"skill":"Knowledge (religion)","value":8},{"skill":"Linguistics","value":4},{"skill":"Perception","value":12},{"skill":"Spellcraft","value":8}],"languages":["Common","Thassilonian"],"sq":["aura"],"gear":"+1 breastplate, masterwork heavy steel shield, +1 flail, masterwork light crossbow, silver holy symbol, spell component pouch, potion of cure serious wounds","before_combat":"If alerted to enemies approaching, the cultists wait until they can hear the PCs on the stairs, and cast magic circle against evil, aid, and entropic shield.","during_combat":"To begin, two cultists take positions facing the stairs and engage the PCs in combat with their crossbows. The other two position themselves along the wall on either side of the staircase exit and lay down blast runes in the four squares directly in front of the stairs, renewing them as needed if the party doesn't take the bait and rush into action. Once the PCs are in the room, all four cultists cast divine favor and engage the party in melee,   using Channel Smite until out of channeling uses. They use their attack spells as needed to hinder the party.","morale":"After losing half their hit points, the cultists cast cure light wounds on themselves. If reduced to 20 or fewer hit points, they drink their potions. Otherwise, the cultists fight to the death in defense of their goddess's holy site.","source":"PFS S3-26"},{"name":"Heshlak Subtier 10-11","cr":9,"xp":6400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":4},{"class":"inquisitor of Lissala","level":6}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":5,"ac":22,"ac_touch":15,"ac_flat_footed":17,"ac_mods":"+5 armor, +4 Dex, +1 dodge, +2 shield","hp":89,"hd":"4d10+6d8+36","hd_value":10,"fort":11,"ref":7,"will":7,"save_mods":"+1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":30}],"melee":"+1 agile whip +14 (1d3+7) or mwk scimitar +10 (1d6+1/18-20)","ranged":"heavy crossbow +12 (1d10/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bane","details":"6 rounds/day"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect alignment"}]},{"frequency":"4/day","spells":[{"spell":"blast rune","details":"6 rounds, 1d6+3 energy damage"}]},{"frequency":"6 rounds/day","spells":[{"spell":"discern lies"}]}],"spellsknown_caster":"inquisitor","spellsknown_caster_level":6,"spellsknown_concentration":6,"spellsknown":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"detect thoughts"},{"spell":"flames of the faithful"},{"spell":"see invisibility"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"bane"},{"spell":"bless"},{"spell":"command"},{"spell":"cure light wounds"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"daze"},{"spell":"light"},{"spell":"read magic"},{"spell":"resistance"},{"spell":"stabilize"}]}],"spelldomains":"Rune","strength":13,"dexterity":18,"constitution":14,"intelligence":8,"wisdom":13,"charisma":10,"baseatk":8,"cmb":12,"cmd":24,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Whip Mastery"},{"feat":"Precise Strike"},{"feat":"Tandem Trip"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (whip)"},{"feat":"Weapon Specialization (whip)"},{"feat":"Whip Mastery"}],"skills":[{"skill":"Intimidate","value":16},{"skill":"Knowledge (religion)","value":7},{"skill":"Linguistics","value":2},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":15},{"skill":"Survival","value":12}],"languages":["Common","Shoanti","Skald","Thassilonian","Varisian"],"sq":["armor training 1","cunning initiative","detect alignment","judgment 2/day","monster lore +1","solo tactics","stern gaze","track +3"],"special_abilities":[{"type":"Judgments","kind":"Su","details":"Heshlak can pronounce judgment on her foes as a swift action. Starting when the judgment is made, she receives a bonus or special ability based on the type of judgment made. Once activated, this ability lasts until the combat ends, at which point all of the bonuses immediately end. She must participate in the combat to gain these bonuses. If she is frightened, panicked, paralyzed, stunned, unsconscious, or otherwise prevented from participating in combat, the ability doesn't end, but the bonuses don't resume until she can participate in the combat again. When Heshlak uses this ability, she must select one type of judgment to make. As a swift action, she can change this judgment to another type. The two judgment types Heshlak uses in this combat are as follows: Protection: Heshlak is surrounded by a protective aura, granting a +2 profane bonus to Armor Class. Destruction: Heshlak is filled with divine wrath, gaining a +3 profane bonus on all weapon damage rolls."},{"type":"Precise Strike","kind":"Ex","details":"Whenever Heshlak and an ally who also has this feat are flanking the same creature, Heshlak deals an additional 1d6 points of precision damage with each successful melee attack. This bonus stacks with other sources of precision damage, and isn't multiplied on a critical hit."}],"gear":"+1 mithral shirt, heavy steel shield, +1 agile whip, masterwork scimitar, heavy crossbow with 20 bolts, spell component pouch, silver holy symbol, potion of cat's grace, potion of cure serious wounds","before_combat":"If warned of the PCs' approach, Heshlak casts bless on herself and the cultists, drinks her potion of cat's grace, and casts flames of the faithful on her whip, granting it the flaming burst weapon special property for 6 rounds (caster level +1 round as a transmutation spell).","during_combat":"Once the PCs are in range, Heshlak casts spiritual weapon on a spellcaster, pronounces a judgment of destruction against the party, and moves forward to threaten any PC entering the room with her whip. She tries to stay out of the PCs' reach, letting cultists engage them while using her whip's reach to dominate the floor, expending a swift action to activate her bane ability, selecting the most common humanoid subtype among the Pathfinders. She positions herself to have multiple PCs within 10 feet, if possible, and uses her action each round to either strike a target of the subtype of her bane ability or to make trip attacks. She gleefully takes attacks of opportunity against anyone within range who provokes them. If attacked, she trips her assailant and steps away, laying into them with the whip if trapped. Confronted by multiple assailants at once, she switches her judgment to protection and lashes about her as best she can.","morale":"Heshlak refuses to surrender. If brought below 15 hit points, and a PC is between her and the opening to the  central well, she attempts a bull rush to knock her enemy and herself into the shaft for a 60-foot drop.","source":"PFS S3-26, Advanced Player's Guide 38"}];
